#!/usr/bin/env python3
"""
cloud-android-mesh-slices-gen — #796: the fleet's port table is ONE declaration
(1_cicd/src/data/debug-ports.json) but a COMPILE INPUT of only the slice each
gradle root needs.

Before: libs/devtools/debug-ports.json was baked into every app's BuildConfig,
so one new package's port moved the tree sha of libs/devtools and the publish
gate rebuilt and republished all 32 apps plus every Cloud-Lib APK (2b6f155b4).

Now: every gradle root that compiles libs:devtools gets <root>/debug-api.json —
its own package(s) with their ports, plus `range` and `fallback` — and
libs/devtools/build.gradle reads THAT file beside the consuming root's
build.json. The slice is in the root's own tree, so it is in that root's publish
identity and nobody else's. Roots named in the table's `full_table_for` bake
the whole table (the Store's probe pings every member).

Which roots: every build.json root whose shared-lib inputs
(cloud_android_lib_closure.inputs, the same answer the ship triggers use)
reach devtools, plus any root that declares `lib_apks` (every Cloud-Lib APK
flavor links core→devtools, lib-apks/app/build.gradle). Which packages:
android.application_id, every forks.*.app_id, and for a lib_apks root one
`<application_id>.<module-with-dashes-stripped>` per shipped module — the
same canonical id the fleet-manifest guard holds the rootfs libs to.

USAGE  cloud-android-mesh-slices-gen.py ROOT            write every slice
       cloud-android-mesh-slices-gen.py ROOT --check    exit 1 if any slice on disk differs
EXIT   0 ok · 1 a package has no port, or (--check) a slice is stale
"""
import glob, json, os, sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
sys.dont_write_bytecode = True
from cloud_android_lib_closure import inputs, lib_edges, shared_libs  # noqa: E402

TABLE = "1_cicd/src/data/debug-ports.json"
SLICE = "debug-api.json"
ROOT_GLOBS = ("a[ac]_*/build.json", "ab_cloud-libs-shared/*/build.json", "a_solutions/*/build.json")
DOC = ("GENERATED by 1_cicd/src/scripts/cloud-android-mesh-slices-gen.py (./build.sh workflow) from %s — "
       "do not edit; this root's slice of the fleet's debug-API port table, read by libs/devtools/build.gradle" % TABLE)


def load(root, rel):
    with open(os.path.join(root, rel), encoding="utf-8") as h:
        return json.load(h)


def packages(root, r, cfg):
    out = set()
    aid = (cfg.get("android") or {}).get("application_id")
    lib_apks = cfg.get("lib_apks")
    # A lib_apks root's application_id is the PREFIX of its N APKs, not a package.
    if aid and not isinstance(lib_apks, dict):
        out.add(aid)
    for fork in (cfg.get("forks") or {}).values():
        if isinstance(fork, dict) and fork.get("app_id"):
            out.add(fork["app_id"])
    if isinstance(lib_apks, dict) and aid:
        scan = lib_apks.get("scan") or []
        excl = set(lib_apks.get("exclude") or {})
        for s in (scan if isinstance(scan, list) else [scan]):
            top = os.path.normpath(os.path.join(root, r, s))
            for m in sorted(os.listdir(top)) if os.path.isdir(top) else []:
                if m not in excl and os.path.isfile(os.path.join(top, m, "build.gradle")):
                    out.add("%s.%s" % (aid, m.replace("-", "")))
    return sorted(out)


def roots(root):
    edges, libs = lib_edges(root), shared_libs(root)
    for pat in ROOT_GLOBS:
        for bj in sorted(glob.glob(os.path.join(root, pat))):
            r = os.path.relpath(os.path.dirname(bj), root)
            try:
                cfg = load(root, bj)
            except ValueError:
                continue
            if "devtools" in inputs(root, r, edges, libs) or isinstance(cfg.get("lib_apks"), dict):
                yield r, cfg


def slices(root):
    """{root_dir: slice_dict}; raises SystemExit naming a package with no port."""
    table = load(root, TABLE)
    ports = {k: v for k, v in table["ports"].items() if not k.startswith("_")}
    full = set(table.get("full_table_for") or [])
    out = {}
    for r, cfg in roots(root):
        pkgs = packages(root, r, cfg)
        if not pkgs:
            sys.exit("%s compiles libs:devtools but declares no package (android.application_id / forks.*.app_id)" % r)
        missing = [p for p in pkgs if p not in ports]
        if missing:
            sys.exit("%s: no port in %s for %s — append it at the next free number below `fallback`"
                     % (r, TABLE, ", ".join(missing)))
        mine = ports if full & set(pkgs) else {p: ports[p] for p in pkgs}
        out[r] = {"_doc": DOC, "range": table["range"], "fallback": table["fallback"],
                  "ports": dict(sorted(mine.items()))}
    return out


def render(s):
    return json.dumps(s, indent=2, ensure_ascii=False) + "\n"


def main(argv):
    root = os.path.abspath(argv[0] if argv else ".")
    check = "--check" in argv
    stale = []
    for r, s in slices(root).items():
        path = os.path.join(root, r, SLICE)
        want = render(s)
        have = open(path, encoding="utf-8").read() if os.path.isfile(path) else None
        if have == want:
            continue
        if check:
            stale.append(r)
        else:
            with open(path, "w", encoding="utf-8") as h:
                h.write(want)
            print("wrote %s/%s (%d port(s))" % (r, SLICE, len(s["ports"])))
    if stale:
        print("STALE " + " ".join("%s/%s" % (r, SLICE) for r in stale))
        print("run ./build.sh workflow (cloud-android-mesh-slices-gen.py) and commit the slices")
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
